import sys, json
import pandas as pd
import numpy as np

def to_float(x):
    return float(x) if pd.notna(x) else None

def main():
    df = pd.read_csv(sys.argv[1])

    facts = []

    # Totals
    tot_rev_tw = df['Revenue_TW'].sum(skipna=True)
    tot_rev_lw = df['Revenue_LW'].sum(skipna=True)
    tot_rev_ly = df['Revenue_LY'].sum(skipna=True)
    tot_units_tw = df['Units_TW'].sum(skipna=True)
    tot_units_lw = df['Units_LW'].sum(skipna=True)
    tot_orders_tw = df['Orders_TW'].sum(skipna=True)
    tot_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": round(float(tot_rev_tw), 2),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": round(float(tot_rev_lw), 2),
        "formula": "sum(Revenue_LW)"
    })
    if df['Revenue_LY'].notna().any():
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": round(float(tot_rev_ly), 2),
            "formula": "sum(Revenue_LY)"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": float(tot_units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": float(tot_units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": float(tot_orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": float(tot_orders_lw),
        "formula": "sum(Orders_LW)"
    })

    # Total WoW
    if tot_rev_lw and not np.isnan(tot_rev_lw) and tot_rev_lw != 0:
        wow = (tot_rev_tw - tot_rev_lw) / tot_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": round(float(wow), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    # Total YoY
    if tot_rev_ly and not np.isnan(tot_rev_ly) and tot_rev_ly != 0:
        yoy = (tot_rev_tw - tot_rev_ly) / tot_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": round(float(yoy), 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    # Top 5 entities by Revenue_TW
    top5 = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(5)
    for _, row in top5.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": round(float(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": row['Entity'], "metric": "rank", "period": "TW",
                "value": float(row['Rank']),
                "formula": "Rank"
            })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": round(float(row['Share_Pct']), 1),
                "formula": "Share_Pct"
            })

    # Top 3 WoW gainers and losers
    wow_df = df.dropna(subset=['WoW_Pct']).sort_values('WoW_Pct', ascending=False)
    for _, row in wow_df.head(3).iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })
    for _, row in wow_df.tail(3).iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "WoW",
            "value": round(float(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

    # Top 3 YoY gainers and losers
    yoy_df = df.dropna(subset=['YoY_Pct']).sort_values('YoY_Pct', ascending=False)
    for _, row in yoy_df.head(3).iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })
    for _, row in yoy_df.tail(3).iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "YoY",
            "value": round(float(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

    # Trim to max 25 facts
    facts = facts[:25]

    print(json.dumps(facts))

if __name__ == "__main__":
    main()
